1791|/***
1792| * MARK: sanitizeCiEnv
1793| * @description Bounds an assignment-provided env bag to a flat map of
1794| *   non-empty string keys to non-empty string values (at most 100 entries,
1795| *   mirroring the backend lifecycle seam): the dispatch payload is
1796| *   backend-curated, but the child environment must stay a string map.
1797| *   Non-objects read as empty so a missing/foreign `env` degrades to
1798| *   today's behaviour. Total on untrusted input.
1799| * @example sanitizeCiEnv({ A: '1', B: 2 }) => { A: '1' }
1800| * @param {unknown} value - Candidate env bag from the dispatch answer/claim.
1801| * @returns {Object} Sanitized string map (possibly empty).
1802| ***/
1803|export function sanitizeCiEnv(value) {
1804|	try {
1805|		if (!value || typeof value !== "object" || Array.isArray(value)) return {};
1806|		const out = {};
1807|		let count = 0;
1808|		for (const [key, val] of Object.entries(value)) {
1809|			if (count >= 100) break;
1810|			if (typeof key !== "string" || !key) continue;
1811|			if (typeof val !== "string" || !val) continue;
1812|			out[key] = val;
1813|			count += 1;
1814|		}
1815|		return out;
1816|	} catch {
1817|		return {};
1818|	}
