{"content":"import Fastify from "/home/[REDACTED]/.kainbain/runner-work/kb-d164fb3f-ed08-4221-814e-e9e3a5d75a1a/api/node_modules/fastify/fastify.js";

const app = Fastify({ logger: false });
let routeOnErrorSeen = null;
app.post(
	"/tasks/:id/complete-execution",
	{
		bodyLimit: 100,
		onError: async (request, reply, error) => {
			routeOnErrorSeen = {
				code: error?.code,
				statusCode: error?.statusCode,
				params: request.params,
				contentLength: request.headers["content-length"],
				url: request.url,
			};
		},
	},
	async () => ({ ok: true }),
);
app.post("/other", async () => ({ ok: true }));

const big = "x".repeat(200);
let res = await app.inject({ method: "POST", url: "/tasks/abc/complete-execution", payload: { s: big } });
console.log("oversize route status:", res.statusCode, res.payload.slice(0, 120));
console.log("route onError seen:", JSON.stringify(routeOnErrorSeen));

routeOnErrorSeen = null;
res = await app.inject({ method: "POST", url: "/tasks/abc/complete-execution", payload: { s: "tiny" } });
console.log("small route status:", res.statusCode, res.payload.slice(0, 80), "onError:", routeOnErrorSeen);

// Probe 2: encapsulated setErrorHandler with reply.send(err) delegation
const app2 = Fastify({ logger: false });
app2.register(async (sub) => {
	sub.setErrorHandler((err, req, reply) => {
		if (err?.code === "FST_ERR_CTP_BODY_TOO_LARGE") {
			console.log("setErrorHandler saw 413 for", req.url, "params:", JSON.stringify(req.params));
		}
		reply.send(err);
	});
	sub.post("/tasks/:id/complete-execution", { bodyLimit: 100 }, async () => ({ ok: true }));
});
res = await app2.inject({ method: "POST", url: "/tasks/zz/complete-execution", payload: { s: big } });
console.log("delegated 413 status:", res.statusCode, res.payload.slice(0, 160));
res = await app2.inject({ method: "POST", url: "/tasks/zz/complete-execution", payload: { s: "tiny" } });
console.log("delegated small status:", res.statusCode, res.payload.slice(0, 80));
