			},
		});
		await assert.rejects(
			runSingleAssignment({
				config,
				client,
				loadHarness: async () => fakeHarness(),
				logger: quiet,
			}),
			/Backend 413/,
		);
		assert.equal(interrupts.length, 1, "generic path still interrupts");
