		const home = fs.mkdtempSync(path.join(os.tmpdir(), "kb-join-"));
		const config = baseConfig({
			credential: "",
			joinToken: "jt",
			home,
			harnessIds: ["mock"],
			autoUpdate: false,
		});
		const registers = [];
		const client = {
			register: async (args) => {
				registers.push(args);
				return registers.length === 1
					? { status: "pending", credential: null }
					: { status: "active", credential: "[REDACTED]" };
			},
			setCredential: (next) => {
				client.credential = next;
